// Generated by the build: the compiled Java bridge (org.modhost.*) as a C array.
#include "mod/BridgeDex.inc"

namespace luahost {

namespace {

// Minecraft Bedrock 1.26.62.1 (libminecraftpe.so, arm64): the shared function the
// GameMode attack path goes through. Offsets are version specific, so the first two
// instructions are checked before hooking. Only used when "attackEvent" is on.
constexpr uintptr_t kRvaAttackSender = 0x1009d290;
constexpr uint32_t kExpectWord0 = 0xd10743ff; // sub sp, sp, #464
constexpr uint32_t kExpectWord1 = 0xa9187bfd; // stp x29, x30, [sp, #384]

// Pass-through detour using 8 integer registers so it stays safe even if the
// real function takes fewer arguments.
using U = uint64_t;
using Fn8 = U (*)(U, U, U, U, U, U, U, U);
Fn8 gOriginal = nullptr;
std::atomic<int> gFirstCalls{0};

U attackDetour(U a0, U a1, U a2, U a3, U a4, U a5, U a6, U a7) {
    LuaHost &host = LuaHost::instance();
    const bool first = gFirstCalls.fetch_add(1) < 3;
    if (first)
        host.guardSet("attack_hook.pending");
    // a2 is 1 on the attack path (assumption from the game's code layout).
    if ((a2 & 1U) != 0) {
        host.onAttack();
        JavaBridge::instance().onAttack();
    }
    const U result = gOriginal(a0, a1, a2, a3, a4, a5, a6, a7);
    if (first)
        host.guardClear("attack_hook.pending");
    return result;
}

uintptr_t moduleBase(const char *name) {
    struct Ctx {
        const char *name;
        uintptr_t base;
    } ctx{name, 0};
    dl_iterate_phdr(
        [](dl_phdr_info *info, size_t, void *data) -> int {
            auto *c = static_cast<Ctx *>(data);
            if (info->dlpi_name && std::string_view(info->dlpi_name).find(c->name) != std::string_view::npos) {
                c->base = info->dlpi_addr;
                return 1;
            }
            return 0;
        },
        &ctx);
    return ctx.base;
}

} // namespace

LuaHostMod &LuaHostMod::instance() {
    static LuaHostMod instance;
    return instance;
}

LuaHostMod::LuaHostMod() : mSelf(*ll::mod::NativeMod::current()) {}

bool LuaHostMod::load() {
    auto &self = getSelf();
    self.getLogger().debug("Loading...");

    std::error_code ec;
    std::filesystem::create_directories(self.getDataDir(), ec);
    if (ec) {
        self.getLogger().error("Failed to create data directory {}: {}", self.getDataDir().string(),
                               ec.message());
        return false;
    }

    std::filesystem::create_directories(self.getConfigDir(), ec);
    if (ec) {
        self.getLogger().error("Failed to create config directory {}: {}",
                               self.getConfigDir().string(), ec.message());
        return false;
    }

    mConfigFile.emplace();
    if (!mConfigFile->load()) {
        self.getLogger().warn("Failed to load typed config");
        return false;
    }
    mConfig = mConfigFile->value();

    self.getLogger().info("Loaded {} from {}", self.getName(), self.getModDir().string());
    return true;
}

void LuaHostMod::installInput() {
#if LUAHOST_HAS_INPUT
    // The SDK has no unregister call, so register once per process.
    static std::atomic<bool> installed{false};
    if (installed.exchange(true))
        return;
    pl::input::registerKeyCallback([](const pl::input::KeyEvent &e) -> bool {
        const bool lua = LuaHost::instance().onKey(e.keyCode, e.isKeyDown, e.unicodeChar);
        const bool java = JavaBridge::instance().onKey(e.keyCode, e.isKeyDown, e.unicodeChar);
        return lua || java;
    });
    pl::input::registerTouchCallback([](const pl::input::TouchEvent &e) -> bool {
        const bool lua = LuaHost::instance().onTouch(e.action, e.pointerId, e.x, e.y);
        const bool java = JavaBridge::instance().onTouch(e.action, e.pointerId, e.x, e.y);
        return lua || java;
    });
    pl::input::registerMouseCallback([](const pl::input::MouseEvent &e) -> bool {
        const bool lua = LuaHost::instance().onMouse(e.button, e.isDown);
        const bool java = JavaBridge::instance().onMouse(e.button, e.isDown);
        return lua || java;
    });
#else
    getSelf().getLogger().warn("This SDK has no Input API; Lua key, touch and mouse events are unavailable.");
#endif
}

uintptr_t LuaHostMod::resolveAttackTarget() {
    auto &log = getSelf().getLogger();
    const uintptr_t base = moduleBase("libminecraftpe.so");
    if (base == 0) {
        log.warn("Could not find libminecraftpe.so base address");
        return 0;
    }
    uintptr_t rva = kRvaAttackSender;
    if (!mConfig.attackRva.empty())
        rva = static_cast<uintptr_t>(std::strtoull(mConfig.attackRva.c_str(), nullptr, 16));
    return base + rva;
}

void LuaHostMod::installAttackHook() {
    auto &self = getSelf();
    LuaHost &host = LuaHost::instance();
    if (host.guardTripped("attack_hook.pending")) {
        self.getLogger().warn("The attack hook crashed the game last time; skipping it. Delete attack_hook.pending in the data folder to retry.");
        return;
    }
    const uintptr_t target = resolveAttackTarget();
    if (target == 0)
        return;
    if (mConfig.attackRva.empty()) {
        const auto *w = reinterpret_cast<const uint32_t *>(target);
        if (w[0] != kExpectWord0 || w[1] != kExpectWord1) {
            self.getLogger().warn("Bytes at the attack target do not match 1.26.62.1; attack event skipped to avoid a crash.");
            return;
        }
    }
    mAttackHook = pl::memory::HookHandle(reinterpret_cast<void *>(target),
                                         reinterpret_cast<void *>(&attackDetour),
                                         reinterpret_cast<void **>(&gOriginal),
                                         pl::memory::HookPriority::Normal);
    if (mAttackHook.installed())
        self.getLogger().info("Attack hook installed at 0x{:x}", target);
    else
        self.getLogger().error("Failed to install attack hook");
}

void LuaHostMod::startJava() {
    auto &self = getSelf();
    LuaHost &host = LuaHost::instance();
    if (host.guardTripped("java_start.pending")) {
        host.log("WARN", "java", "Starting Java mods crashed the game last time; skipping them. Delete java_start.pending in the mod's data folder to retry.");
        return;
    }
    std::error_code ec;
    const std::filesystem::path modsDir = host.extDir() / "java_mods";
    std::filesystem::create_directories(modsDir, ec);

    host.guardSet("java_start.pending");
    JavaBridge::instance().start(
        self, mConfig, modsDir, host.dataDir() / "java_data", host.dataDir() / "java_cache",
        [](JNIEnv *e) { return JavaBridge::createInMemoryDexLoader(e, kBridgeDex, kBridgeDexSize); });
    host.guardClear("java_start.pending");
}

bool LuaHostMod::enable() {
    auto &self = getSelf();
    self.getLogger().debug("Enabling...");
    if (!mConfig.enabled) {
        self.getLogger().info("Disabled by config");
        return true;
    }

    LuaHost::instance().start(self, mConfig);
    if (mConfig.javaMods)
        startJava();
    installInput();
    if (mConfig.attackEvent)
        installAttackHook();
    return true;
}

bool LuaHostMod::disable() {
    getSelf().getLogger().debug("Disabling...");
    mAttackHook.reset();
    JavaBridge::instance().stop();
    LuaHost::instance().stop();
    return true;
}

bool LuaHostMod::unload() {
    getSelf().getLogger().debug("Unloading...");
    mConfigFile.reset();
    return true;
}

} // namespace luahost
